#define _POSIX_C_SOURCE 200809L #include <errno.h> #include <stdio.h> #include <sys/wait.h> #include <unistd.h> int main(void) { int x = 5; pid_t pid = fork(); if (pid < 0) { perror("fork"); return 1; } if (pid == 0) { x += 2; printf("child: x=%d, pid=%ld, ppid=%ld\n", x, (long)getpid(), (long)getppid()); return 0; } pid_t r; do { r = waitpid(pid, NULL, 0); } while (r == -1 && errno == EINTR); if (r == -1) { perror("waitpid"); return 1; } printf("parent: x=%d, child=%ld\n", x, (long)pid); return 0; }